{"code":"import json
import numpy as np
import pandas as pd

with open("evaluations.json") as f:
    data = json.load(f)

rows = []
for d in data:
    if d["iteration"] in [2, 4, 5, 6, 7, 8, 9, 10, 11, 12]:
        row = {"iter": d["iteration"], "y": d["target_dissimilarity"]}
        for item in d["recipe"]:
            row[item["ingredient"]] = item["fraction"]
        rows.append(row)

df = pd.DataFrame(rows)
cols = ["pea protein", "sunflower oil", "potato protein", "tapioca starch", "methylcellulose", "flavours", "yeast extract", "liquid smoke", "natural vegetable color"]
x5 = df[df["iter"] == 5][cols].values[0]

print("Differences from Iteration 5 (y = 0.373407):")
for _, r in df.sort_values("y").iterrows():
    diff = r[cols].values - x5
    diff_str = ", ".join([f"{c.split()[0]}:{v:+.2f}" for c, v in zip(cols, diff) if abs(v) > 1e-6])
    if not diff_str:
        diff_str = "EXACT ITER 5"
    print(f"Iter {int(r['iter']):2d} (y={r['y']:.4f}): {diff_str}")
"}
